        say(G, `\u70AD\u304C\u5F31\u308B\uFF1A\u706B\u529B${w.h0 ?? h1}\u2192${h1}${w.burnt ? `\uFF08\u70AD${w.burnt}\u3064\u304C\u7070\u306B\u306A\u3063\u305F\uFF09` : ""}${w.winds ? `\uFF08\u98A8\u9632\u3067${w.winds}\u56DE\u53D7\u3051\u305F\uFF09` : ""}`, p.index);
        emit2(G, { t: "cooled", p: p.index, from: w.h0 ?? h1, to: h1, burnt: w.burnt || 0 });
