    bowlArt = (bowlId, packed) => !packed && bowlId === "funnel" ? SHOP_EQUIPMENT_ART.kumogama_phunnel.url : making((BOWL_ART[bowlId] || BOWL_ART.clay)[packed ? 1 : 0]);
    HMD_ART = { lotus: "lotos_hagal", amaburst: "amaburst_hms", tanukish: "tanukish_lid", big_tanukish: "tanukish_lid" };
