    move(cam, [{ transform: "translate(0px, 0px) scale(1)" }, { transform: camAt(...camIn) }], 600, { easing: CAM });
    move(stripes, [{ transform: "scale(1)" }, { transform: "scale(1.18)" }], 600, { easing: CAM });
