    pen.g.style.opacity = "1";
    await penHop(pen, [first[0] + 26, first[1] - 36], 320, { lift: 30, land: 30, ang: 30 });
    capOff(pen, print.top, first[0] + 26, first[1] - 36, INK_COLOR.p);
    await sleep(110);
    await dev;
    await penHop(pen, first, 80, { lift: 0 });
