    twinkle(fxArt, box2.left + box2.width - 18, box2.top + box2.height - 92, { color: P2.main, size: 22, dur: 240 });
    twinkle(fxArt, box2.left + 16, box2.top + box2.height - 30, { color: P2.mid, size: 16, delay: 80, dur: 240 });
