function blobPath(R4) {
  const n2 = 40;
  const f = [Math.random() * 6, Math.random() * 6, Math.random() * 6];
  const pts2 = Array.from({ length: n2 }, (_, i) => {
    const t = i / n2 * Math.PI * 2;
    const r = R4 * (1 + 0.11 * Math.sin(3 * t + f[0]) + 0.07 * Math.sin(5 * t + f[1]) + 0.04 * Math.sin(8 * t + f[2]));
    return [Math.cos(t) * r, Math.sin(t) * r];
  });
  let d = `M ${pts2[0][0].toFixed(1)} ${pts2[0][1].toFixed(1)}`;
  for (let i = 0; i < n2; i++) {
    const [p0, p1, p2, p3] = [-1, 0, 1, 2].map((o) => pts2[(i + o + n2) % n2]);
    const c1 = [p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6];
    const c22 = [p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6];
    d += ` C ${c1[0].toFixed(1)} ${c1[1].toFixed(1)} ${c22[0].toFixed(1)} ${c22[1].toFixed(1)} ${p2[0].toFixed(1)} ${p2[1].toFixed(1)}`;
  }
  return `${d} Z`;
}
function strokeRoute() {
  const rows = [120, 360, 600], left = -60, right = W + 60, turn = 120;
  const pts2 = [];
  rows.forEach((y, r) => {
    const ltr = r % 2 === 0;
    for (let s = 0; s <= 1.0001; s += 1 / 90) {
      const x = ltr ? mix2(left, right, s) : mix2(right, left, s);
      pts2.push([x, y + 12 * Math.sin(x / 38 + r * 2)]);
    }
    if (r < rows.length - 1) {
      const cx = ltr ? right : left;
      for (let s = 1; s < 24; s++) {
        const a12 = -Math.PI / 2 + s / 24 * Math.PI;
        pts2.push([cx + (ltr ? 1 : -1) * Math.cos(a12) * turn, y + turn + Math.sin(a12) * turn]);
      }
    }
  });
  const lens = [0];
  for (let i = 1; i < pts2.length; i++) lens.push(lens[i - 1] + Math.hypot(pts2[i][0] - pts2[i - 1][0], pts2[i][1] - pts2[i - 1][1]));
  const total = lens[lens.length - 1];
  const at5 = (d) => {
    let i = 1;
    while (i < lens.length - 1 && lens[i] < d) i++;
    const k = (d - lens[i - 1]) / (lens[i] - lens[i - 1] || 1);
    const [x0, y0] = pts2[i - 1], [x1, y1] = pts2[i];
    return { x: mix2(x0, x1, k), y: mix2(y0, y1, k), dx: (x1 - x0) / (lens[i] - lens[i - 1] || 1) };
  };
  return { d: `M ${pts2.map(([x, y]) => `${x.toFixed(1)} ${y.toFixed(1)}`).join(" L ")}`, total, at: at5 };
}
