function drawHistory(items, ui) {
  const draw3 = () => {
    let lastItem = null;
    for (const it of items) {
      if (!lastItem || it.day !== lastItem.day || it.chapter !== lastItem.chapter) {
        ui.note(dayLabel(it), ".day");
        lastItem = it;
      }
      if (!it.read) continue;
      for (const msg of it.msg.messages || []) drawMessage(ui, msg, msg?.me === true, accountOf(it), false);
      const missed = missedInvitationNote(it);
      if (missed) {
        ui.note(missed);
        continue;
      }
      for (const l of it.log || []) {
        if (l.note) ui.note(l.note);
        else drawMessage(ui, l, l.me, accountOf(it), false);
      }
    }
  };
  if (typeof ui.withDeferredScroll === "function") ui.withDeferredScroll(draw3);
  else draw3();
}
