async function openPhone(messages, { title: title2 = null, time = "\u671D" } = {}) {
  const accepted = [];
  const ui = phoneShell({ time, title: title2 || (state.phase === "tournament" ? "\u5927\u4F1A\u5F53\u65E5" : `DAY ${chapterDay(state)}`) });
  await sleep(420);
  if (!ui.live(ui.gen)) return accepted;
  for (const m of messages) {
    const item2 = receiveItem(m);
    state.inbox.push(item2);
    ui.chat.replaceChildren();
    ui.actions.replaceChildren();
    ui.lastSide = null;
    const left = messages.length - 1 - messages.indexOf(m);
    ui.header.replaceChildren(
      el("span.lime-logo", { text: "LIME" }),
      el("div.lime-peer", [avatar(accountOf(item2)), el("span.lime-name", { text: limeName(accountOf(item2)) })]),
      el("span.lime-unread", { text: left ? `\u672A\u8AAD ${left}` : "" })
    );
    await runItem(item2, ui, accepted, { forced: true });
    if (!ui.live(ui.gen)) return accepted;
    item2.done = true;
    await new Promise((resolve) => {
      const last = messages.at(-1) === m;
      ui.actions.replaceChildren(el(`button.lime-reply.ghost${m.close_label ? ".multiline" : ""}`, {
        text: m.close_label || (last ? "\u30B9\u30DE\u30DB\u3092\u9589\u3058\u308B" : "\u6B21\u306E\u30C8\u30FC\u30AF \u25B8"),
        dataset: { test: "phone-next" },
        onclick: () => {
          SE.click();
          resolve();
        }
      }));
      ui.scroll();
    });
  }
  await ui.close();
  return accepted;
}
function limeCoach(onOpen) {
  if (state.flags._lime_tut || !hasUnread()) return false;
  const icon4 = document.querySelector(".hud-lime");
  const stage2 = document.getElementById("stage");
  if (!icon4 || !stage2) return false;
  state.flags._lime_tut = 1;
  const k = stage2.getBoundingClientRect().width / stage2.offsetWidth || 1;
  const sr = stage2.getBoundingClientRect();
  const ir = icon4.getBoundingClientRect();
  const x = (ir.left - sr.left) / k;
  const y = (ir.top - sr.top) / k;
  const w = ir.width / k;
  const h = ir.height / k;
  const owner = state;
  let opened = false;
  const open = () => {
    if (opened || state !== owner || !coach.isConnected) return;
    opened = true;
    SE.select();
    coach.remove();
    onOpen();
  };
  const coach = el("div.lime-coach", [
    el("button.lc-hole", {
      type: "button",
      "aria-label": "LIME\u3092\u958B\u304F",
      style: { left: `${x - 8}px`, top: `${y - 8}px`, width: `${w + 16}px`, height: `${h + 16}px` },
      dataset: { test: "coach-lime" },
      onclick: open
    }),
    el("button.lc-bubble", {
      type: "button",
      "aria-label": "\u6848\u5185\u304B\u3089LIME\u3092\u958B\u304F",
      dataset: { test: "coach-lime-bubble" },
      onclick: open,
      style: { right: `${Math.max(16, stage2.offsetWidth - x - w - 4)}px`, top: `${y + h + 22}px` }
    }, [
      el("b", { text: "LIME\u306B\u30E1\u30C3\u30BB\u30FC\u30B8\u304C\u5C4A\u3044\u305F\uFF01" }),
      el("span", { text: "\u3053\u306E\u6848\u5185\u304B\u53F3\u4E0A\u306ELIME\u3092\u30BF\u30C3\u30D7\u3057\u3066\u958B\u3044\u3066\u307F\u3088\u3046\u3002" }),
      el("span", { text: "\u307E\u305A\u306F\u4E00\u5EA6\u958B\u3044\u3066\u307F\u3088\u3046\u3002\u6B21\u304B\u3089\u306F\u597D\u304D\u306A\u3068\u304D\u306B\u8AAD\u3081\u308B\u3002\u8FD4\u4E8B\u3084\u8A98\u3044\u306E\u53D7\u8AFE\u306F\u3001\u4ECA\u6C7A\u3081\u306A\u304F\u3066\u5927\u4E08\u592B\u3002" })
    ])
  ]);
  layers2.fx.append(coach);
  SE.phoneReceive();
  return true;
}
